head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25710";

// [A] 초기 목록 미해결 — jldfil25710: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25710.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_application
 * @description application 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_application = async function () {
    const sbmOptions = {
        id: "tx_fn_application",
        method: "post",
        action: "/account/advceComInfo.do",
        ref: "dma_applicationReq",
        target: "dlt_advceComInfoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/account/advceComInfo.do",
        ref: "dma_deleteReq",
        target: "dlt_advceComInfoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name application
 * @description application 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.application = async function () {
    const str = "자문기업 추가/삭제 신청은\n[자문기업신청현황] 메뉴에서 신청가능합니다.\n 해당 메뉴로 이동하시겠습니까?";
    if (await $c.win.confirm(str)) {
        (document.advceComInfoForm || { elements: [] }).action = "/account/advceComInfo.do";
        $c.util.getComponent('dma_applicationReq').set('method', "advceComApplList");
        const nr = await scwin.tx_fn_application();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil25720/jldfil25720.xml", { "method": "advceComApplList" });
        }
    }
};

/**
 * @method
 * @name deleteApplicationReq
 * @description delete Application Req 처리
 * @param {String} advceComIsurCd advceComIsurCd
 * @param {String} comNm comNm
 * @param {String} advceComApplTpCd advceComApplTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteApplicationReq = async function (advceComIsurCd, comNm, advceComApplTpCd) {
    (document.advceComInfoForm || { elements: [] }).action = "/account/advceComInfo.do";
    $c.util.getComponent('dma_applicationReq').set('method', "advceComInfoApply");
    $c.util.getComponent('dma_applicationReq').set('advceComIsurCd', advceComIsurCd);
    $c.util.getComponent('dma_applicationReq').set('advceComApplTpCd', advceComApplTpCd);
    const str = "『" + comNm + "』의 지정자문법인여부를 삭제요청하시겠습니까?";
    if (await $c.win.confirm(str)) {
        $c.util.getComponent('dma_applicationReq').set('applStat', "1");
        const nr = await scwin.tx_fn_delete();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil25720/jldfil25720.xml", { "method": "advceComInfoApply", "advceComIsurCd": advceComIsurCd, "advceComApplTpCd": advceComApplTpCd, "applStat": "1" });
        }
    }
};
